// Which store each cache uses comes from the environment, so a change is an
// apply. An unknown name throws, so the new container never gets healthy and
// the old one keeps serving.
$fwCacheTypes = [
	'none' => CACHE_NONE,
	'db' => CACHE_DB,
	'memcached' => CACHE_MEMCACHED,
	'memcached-pecl' => 'femiwiki-memcached-pecl',
	'apcu' => CACHE_ACCEL,
	'anything' => CACHE_ANYTHING,
];
// The same memcached through the C client. Each client reads the other's values
// as something else (an array as 0, a compressed string as raw bytes), and old
// and new containers share memcached during a swap, so this one keeps its keys
// under a prefix of their own, global keys included.
$wgObjectCaches['femiwiki-memcached-pecl'] = [
	'class' => \Wikimedia\ObjectCache\MemcachedPeclBagOStuff::class,
	'loggroup' => 'memcached',
	'routingPrefix' => 'pecl/',
	// WANObjectCache sets are noreply, so with Nagle on the next command waits out
	// memcached's delayed ACK: about 45 ms per set (#1807)
	'allow_tcp_nagle_delay' => false,
];
// $default is not typed: CACHE_MEMCACHED is the string 'memcached-php' and
// CACHE_DB is the integer 1, so these constants have no one type.
$fwCacheType = static function ( string $name, $default ) use ( $fwCacheTypes ) {
	$value = getenv( $name );
	if ( $value === false || $value === '' ) {
		return $default;
	}
	if ( !array_key_exists( $value, $fwCacheTypes ) ) {
		throw new RuntimeException(
			"$name is \"$value\", which is not one of: " . implode( ', ', array_keys( $fwCacheTypes ) )
		);
	}
	return $fwCacheTypes[$value];
};

