// VisualEditor
// Namespaces in which to enable VisualEditor
$wgVisualEditorAvailableNamespaces = [
	NS_SPECIAL => true,
	NS_MAIN => true,
	NS_TALK => true,
	NS_USER => true,
	NS_USER_TALK => true,
	NS_PROJECT => true,
	NS_PROJECT_TALK => true,
	NS_FILE => true,
	NS_FILE_TALK => true,
	NS_MEDIAWIKI => true,
	NS_MEDIAWIKI_TALK => true,
	NS_TEMPLATE => true,
	NS_TEMPLATE_TALK => true,
	NS_HELP => true,
	NS_HELP_TALK => true,
	NS_CATEGORY => true,
	NS_CATEGORY_TALK => true,
	'_merge_strategy' => 'array_plus',
];

// Widgets
$wgNamespaceContentModels[274] = CONTENT_MODEL_TEXT;

// WikiBase - repo
wfLoadExtension( 'WikibaseRepository', "$IP/extensions/Wikibase/extension-repo.json" );
require_once "$IP/extensions/Wikibase/repo/ExampleSettings.php";
$wgWBRepoSettings['enableEntitySearchUI'] = false;
$wgWBRepoSettings['siteLinkGroups'] = [ 'femiwiki' ];
$wgWBRepoSettings['conceptBaseUri'] = $wgCanonicalServer . str_replace( '$1', 'Item:', $wgArticlePath );
$wgWBRepoSettings['statementSections'] = [
	'item' => [
		'statements' => null,
		'identifiers' => [
			'type' => 'dataType',
			'dataTypes' => [ 'external-id' ],
		],
	],
];
$wgWBRepoSettings['formatterUrlProperty'] = 'P61';

// WikibaseQualityConstraints
wfLoadExtension( 'WikibaseQualityConstraints' );
// Femiwiki's own property and item IDs are in LocalSettings.yaml
// Wikidata uses one property for both
$wgWBQualityConstraintsConstraintEntityTypesId = $wgWBQualityConstraintsConstraintScopeId;
$wgWBRepoSettings['statementSections']['property'] = [
	'statements' => null,
	'constraints' => [
		'type' => 'propertySet',
		'propertyIds' => [ $wgWBQualityConstraintsPropertyConstraintId ],
	],
];

// PropertySuggester, with statistics counted from Femiwiki's own items by
// PropertySuggesterLocalStats (femiwiki/docker-mediawiki#522)
wfLoadExtension( 'PropertySuggester' );
wfLoadExtension( 'PropertySuggesterLocalStats' );

// WikiBase - client
wfLoadExtension( 'WikibaseClient', "$IP/extensions/Wikibase/extension-client.json" );
require_once "$IP/extensions/Wikibase/client/ExampleSettings.php";
// Wikibase's translated name, as on Special:SpecialPages
$wgWBClientSettings['repoSiteName'] = 'specialpages-group-wikibase';
// Defaults to $wgDBname, while sitelinks and subscriptions are stored as femiwiki
$wgWBClientSettings['siteGlobalID'] = 'femiwiki';

// WikiEditor
wfLoadExtension( 'WikiEditor' );

// WikiSEO
wfLoadExtension( 'WikiSEO' );

//
// Overwrite server url
//
if ( getenv( 'MEDIAWIKI_SERVER' ) ) {
	$wgServer = getenv( 'MEDIAWIKI_SERVER' );
	$wgForceHTTPS = substr( $wgServer, 0, 5 ) === 'https';
	$wgCanonicalServer = $wgServer;
	$wgWBRepoSettings['conceptBaseUri'] = $wgServer . '/w/Item:';
	// No fedi host here, so actor ids use the REST route on this server
	$wgFediFeedsActorBase = null;
	// Nothing outside can reach these actors, so no bridge would take their follows
	$wgFediFeedsAutoFollow = [];
}

//
// Debug Mode
//
if ( getenv( 'MEDIAWIKI_DEBUG_MODE' ) ) {
	// 디버그 툴 활성화
	require_once "includes/DevelopmentSettings.php";
	// It adds site.v1.json again, which REST refuses as a duplicate module
	$wgRestAPIAdditionalRouteFiles = array_values( array_unique( $wgRestAPIAdditionalRouteFiles ) );
	// 위키베이스 속성 초기화. Not in LocalSettings.dev.yaml, which would replace the whole array.
	$wgWBRepoSettings['formatterUrlProperty'] = null;
	// The plain values, after DevelopmentSettings.php so they override it
	$wgSettings->loadFile( '/etc/mediawiki/LocalSettings.dev.yaml' )->apply();
}

// Settings infra passes as a JSON object of global names to values, after the
// defaults above so it overrides them
$fwSettings = getenv( 'FW_SETTINGS' );
if ( $fwSettings ) {
	foreach ( json_decode( $fwSettings, associative: true, flags: JSON_THROW_ON_ERROR ) as $fwName => $fwValue ) {
		$GLOBALS[$fwName] = $fwValue;
	}
	unset( $fwName, $fwValue );
}
unset( $fwSettings );

require_once '/etc/mediawiki/Hotfix.php';

// Class map of the extensions loaded above, written at build by
// autoload-extensions.php, so the autoloader reads a path instead of testing
// PSR-4 candidates with is_file() on every request. Last, after anything the
// hotfix loads.
if ( is_readable( '/etc/mediawiki/autoload-extensions.php' ) ) {
	$fwAutoload = require '/etc/mediawiki/autoload-extensions.php';
	foreach ( MediaWiki\Registration\ExtensionRegistry::getInstance()->getQueue() as $fwManifest => $fwMtime ) {
		AutoLoader::registerClasses( $fwAutoload[$fwManifest] ?? [] );
	}
	unset( $fwAutoload, $fwManifest, $fwMtime );
}
